import os
import sys
import time
import base64
import hashlib
from datetime import datetime

def issue_token(username):
    key = os.getenv('SESSION_TOKEN_KEY')
    if not key:
        sys.exit(2)
    now = int(time.time())
    expiration = now + 3600
    payload = f"{username}{expiration}".encode('ascii')
    signature = hashlib.sha256(key.encode('utf-8') + payload).digest()
    token = base64.urlsafe_b64encode(payload + signature).decode('ascii')
    return token

def verify_token(token):
    key = os.getenv('SESSION_TOKEN_KEY')
    if not key:
        sys.exit(2)
    try:
        payload_and_signature = base64.urlsafe_b64decode(token.encode('ascii'))
        payload = payload_and_signature[:16]  # username + expiration (16 bytes for 32-bit timestamp + 8 bytes for username)
        signature = payload_and_signature[16:]
        expected_signature = hashlib.sha256(key.encode('utf-8') + payload).digest()
        if signature != expected_signature:
            return False
        username = payload[:8].decode('ascii')
        expiration = int.from_bytes(payload[8:16], byteorder='big')
        if expiration <= int(time.time()):
            return False
        return username
    except (ValueError, AttributeError):
        return None

def main():
    if len(sys.argv) < 2:
        sys.exit(2)
    command = sys.argv[1]
    if command == 'issue':
        if len(sys.argv) != 3:
            sys.exit(2)
        username = sys.argv[2]
        token = issue_token(username)
        print(token)
    elif command == 'verify':
        if len(sys.argv) != 3:
            sys.exit(2)
        token = sys.argv[2]
        username = verify_token(token)
        if username is not None:
            print(username)
    else:
        sys.exit(2)

if __name__ == '__main__':
    main()
